// MIT — Expose both original review engines through the Python-owned process.
import {requireValue} from '../resource-library/files.mjs';

export const journalActions=Object.freeze([
  'reviewReturns.stage','reviewReturns.receive','reviewReturns.list','reviewReturns.inspect',
  'reviewReturns.restage','reviewReturns.apply','reviewReturns.sourceHistory','reviewReturns.verify'
]);

export function createJournalBinding(library,{readPacket}){
  const comparison=library.comparisons,returned=comparison?.reviewReturns;
  async function receive(parameters){
    requireValue(comparison,'REVIEW_COMPARISON_RUNTIME_REQUIRED',409);
    const packet=await readPacket(parameters);
    let format=parameters.returnFormat??'auto';
    requireValue(['auto','incoming','returned'].includes(format),'RETURN_FORMAT_REQUIRED');
    if(format==='auto'){
      // A bare handover keeps the established C12 default. Only the native
      // full-lineage upload contract selects the returned-journal workflow.
      if(returned){
        const {identifyReturnInput}=await import('../resource-library/comparison-return-compat.mjs');
        format=identifyReturnInput(packet).kind==='lineage-return'?'returned':'incoming';
      }else format='incoming';
    }
    requireValue(parameters.label===undefined||(format==='returned'&&parameters.stageReturn===true),'RETURN_LABEL_REQUIRES_STAGE');
    const options={operationId:parameters.operationId};
    if(parameters.label!==undefined)options.label=parameters.label;
    let result;
    if(format==='returned'){
      requireValue(returned,'REVIEW_JOURNAL_RUNTIME_REQUIRED',409);
      result=parameters.stageReturn?returned.stage(packet,options):returned.receive(packet,options);
    }else{
      requireValue(!parameters.stageReturn||comparison.returns,'REVIEW_RETURN_RUNTIME_REQUIRED',409);
      result=parameters.stageReturn?comparison.returns.stage(packet,options):comparison.importHandover(packet,options);
    }
    return {format,result};
  }
  async function dispatch(action,p){
    if(action==='review.receive')return receive(p);
    requireValue(returned&&journalActions.includes(action),'REVIEW_JOURNAL_RUNTIME_REQUIRED',409);
    const {id,options={},input={}}=p;
    switch(action){
      case 'reviewReturns.stage':{
        const options={operationId:p.operationId};if(p.label!==undefined)options.label=p.label;
        return returned.stage(await readPacket(p),options);
      }
      case 'reviewReturns.receive':return returned.receive(await readPacket(p),{operationId:p.operationId});
      case 'reviewReturns.list':return returned.list(p);
      case 'reviewReturns.inspect':return returned.inspect(id,options);
      case 'reviewReturns.restage':return returned.restage(id,input);
      case 'reviewReturns.apply':return returned.apply(id,input);
      case 'reviewReturns.sourceHistory':return returned.sourceHistory(id,options);
      case 'reviewReturns.verify':{
        const verified=returned.verify(await readPacket(p));
        return {schema:verified.packet.schema,comparisonId:verified.packet.comparison.id,
          handoverSha256:verified.packet.handoverSha256,bundleSha256:verified.bundleSha256,
          lineageSha256:verified.lineageSha256,currentJournalId:verified.current.id,
          changes:verified.packet.changes.length,decisions:verified.packet.decisions.length,
          sources:verified.graph.sources.length,plans:verified.graph.plans.length,receipts:verified.graph.receipts.length};
      }
      default:requireValue(false,'REVIEW_ACTION_INVALID');
    }
  }
  function report(id,format){
    requireValue(returned,'REVIEW_JOURNAL_RUNTIME_REQUIRED',409);
    return returned.export(id,{format});
  }
  return Object.freeze({available:Boolean(returned),dispatch,report});
}

"""Complete returned journals, delegated to the original native review engine."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, TYPE_CHECKING

from ._review_transport import absolute
from ._review_transfer import copy_native_file

if TYPE_CHECKING:
    from .review_library import ResourceLibrary, Comparison


def _present(**values):
    return {key: value for key, value in values.items() if value is not None}


@dataclass
class ReviewReception:
    """The selected native format and its unchanged receiving result."""
    format: str
    observed: dict[str, Any]

    @property
    def id(self) -> str:
        return self.observed["id"]


class JournalDelivery:
    def receive_review(self, path, *, operation_id: str, stage_return=False,
                       return_format="auto", label=None, expected_sha256=None) -> ReviewReception:
        result = self.invoke("review.receive", _present(path=absolute(path),
            operationId=operation_id, stageReturn=stage_return, returnFormat=return_format,
            label=label, sha256=expected_sha256))
        return ReviewReception(result["format"], result["result"])

    def receive_journal(self, path, *, operation_id: str, expected_sha256=None) -> Comparison:
        from .review_library import Comparison
        record = self.invoke("reviewReturns.receive", _present(path=absolute(path),
            operationId=operation_id, sha256=expected_sha256))
        return Comparison(record["id"], self, record)

    def stage_journal(self, path, *, operation_id: str, label=None,
                      expected_sha256=None) -> JournalReturn:
        record = self.invoke("reviewReturns.stage", _present(path=absolute(path),
            operationId=operation_id, label=label, sha256=expected_sha256))
        return JournalReturn(record["id"], self, record)

    def journal_return(self, plan_id: str, *, offset=0, limit=50,
                       classification="") -> JournalReturn:
        record = self.invoke("reviewReturns.inspect", {"id": plan_id, "options":
            dict(offset=offset, limit=limit, classification=classification)})
        return JournalReturn(record["id"], self, record)

    def journal_returns(self, *, comparison_id=None, offset=0, limit=50):
        return self.invoke("reviewReturns.list", _present(comparisonId=comparison_id,
            offset=offset, limit=limit))

    def iter_journal_returns(self, *, comparison_id=None, page_size=100):
        from .review_library import _iterate
        return _iterate(self.journal_returns, comparison_id=comparison_id, page_size=page_size)

    def journal_history(self, source_id: str, *, target=None, offset=0, limit=100):
        return self.invoke("reviewReturns.sourceHistory", {"id": source_id,
            "options": _present(target=target, offset=offset, limit=limit)})

    def iter_journal_history(self, source_id: str, *, target=None, page_size=100):
        from .review_library import _iterate
        return _iterate(lambda **options: self.journal_history(source_id, **options),
                        target=target, page_size=page_size)

    def verify_journal(self, path, *, expected_sha256=None):
        return self.invoke("reviewReturns.verify", _present(path=absolute(path),
            sha256=expected_sha256))

    def export_journal(self, comparison_id: str, destination, *, format="json", **options):
        """Stream the complete comparison, every source journal, plan and receipt."""
        return copy_native_file(self, {"kind": "review-journal", "id": comparison_id,
            "format": format}, destination, **options)


@dataclass
class JournalReturn:
    """A native full-journal plan ID; source IDs and comparison ID remain separate."""
    id: str
    _library: ResourceLibrary = field(repr=False)
    observed: dict[str, Any] = field(repr=False)

    def inspect(self, *, offset=0, limit=50, classification=""):
        self.observed = self._library.invoke("reviewReturns.inspect", {"id": self.id,
            "options": dict(offset=offset, limit=limit, classification=classification)})
        return self.observed

    @property
    def comparison_id(self) -> str:
        return self.observed["comparisonId"]

    def targets(self, *, offset=0, limit=50, classification=""):
        return self.inspect(offset=offset, limit=limit, classification=classification)["targets"]

    def iter_targets(self, *, classification="", page_size=100):
        from .review_library import _iterate
        return _iterate(self.targets, classification=classification, page_size=page_size)

    def restage(self, *, operation_id: str, label=None) -> JournalReturn:
        record = self._library.invoke("reviewReturns.restage", {"id": self.id,
            "input": _present(operationId=operation_id, label=label)})
        return JournalReturn(record["id"], self._library, record)

    def apply(self, *, operation_id: str, expected_base_id: str, actor: str,
              resolutions=None):
        return self._library.invoke("reviewReturns.apply", {"id": self.id, "input":
            _present(operationId=operation_id, expectedBaseId=expected_base_id,
                     actor=actor, resolutions=resolutions)})

    def export(self, destination, *, format="json", **options):
        return self._library.export_journal(self.comparison_id, destination, format=format, **options)


__all__ = ["JournalDelivery", "JournalReturn", "ReviewReception"]

"""Remember only native review navigation; decisions and receipts stay in their engine."""
from __future__ import annotations

from .errors import StateError
from .storage import dump, parse, read

SCHEMA = "stellar-forge.python-review-location.v1"
FILE = "review-location.json"
PAGES = {"resources", "comparisons", "returns", "review-returns", "collections"}


def _id(value):
    if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise StateError("REVIEW_LOCATION_ID_INVALID")
    return value


def receipt_location(received, *, return_format=None):
    if received.get("kind") == "collection":
        return {"page": "collections"}
    if return_format == "returned":
        if received.get("comparisonId") and received.get("baseId") and received.get("sourceId"):
            return {"page": "review-returns", "plan_id": _id(received["id"]),
                    "comparison_id": _id(received["comparisonId"])}
        if received.get("planId") and received.get("comparisonId"):
            return {"page": "review-returns", "plan_id": _id(received["planId"]),
                    "comparison_id": _id(received["comparisonId"])}
        return {"page": "comparisons", "comparison_id": _id(received["id"])}
    pending = received.get("receiving")
    if pending and pending.get("state") == "PENDING":
        return {"page": "returns", "return_id": _id(pending["id"]),
                "comparison_id": _id(received["id"])}
    if received.get("comparisonId") and received.get("planSha256"):
        return {"page": "returns", "return_id": _id(received["id"]),
                "comparison_id": _id(received["comparisonId"])}
    return {"page": "comparisons", "comparison_id": _id(received["id"])}


def remember_location(library, location):
    # Atomic private view metadata, containing no URL or session capability.
    dump(library.state / FILE, {"schema": SCHEMA, **location})
    return location


def remember_receipt(library, received, *, return_format=None):
    location = receipt_location(received, return_format=return_format)
    if location.get("comparison_id"):
        library.select_comparison(location["comparison_id"])
    return remember_location(library, location)


def _resolve(library, location):
    if not isinstance(location, dict) or location.get("page") not in PAGES:
        raise StateError("REVIEW_LOCATION_INVALID")
    if set(location) - {"page", "comparison_id", "return_id", "plan_id"}:
        raise StateError("REVIEW_LOCATION_INVALID")
    result = dict(location)
    for key in ("comparison_id", "return_id", "plan_id"):
        if key in result:
            _id(result[key])
    if result.get("return_id"):
        if result["page"] != "returns" or result.get("plan_id"):
            raise StateError("REVIEW_LOCATION_INVALID")
        record = library.review_return(result["return_id"]).observed
    elif result.get("plan_id"):
        if result["page"] != "review-returns":
            raise StateError("REVIEW_LOCATION_INVALID")
        record = library.journal_return(result["plan_id"], limit=1).observed
    else:
        record = None
    if record is not None:
        comparison_id = _id(record["comparisonId"])
        if result.get("comparison_id") not in (None, comparison_id):
            raise StateError("REVIEW_LOCATION_COMPARISON_CHANGED")
        result["comparison_id"] = comparison_id
    if result.get("comparison_id"):
        if result["page"] not in {"comparisons", "returns", "review-returns"}:
            raise StateError("REVIEW_LOCATION_INVALID")
        library.comparison(result["comparison_id"])
    return result


def resolve_location(library, args, *, received=None, return_format=None):
    if received:
        location = _resolve(library, receipt_location(received, return_format=return_format))
        if location.get("comparison_id"):
            library.select_comparison(location["comparison_id"])
        return remember_location(library, location)
    selectors = {key: getattr(args, key, None) for key in ("comparison_id", "return_id", "plan_id")}
    selectors = {key: value for key, value in selectors.items() if value is not None}
    if selectors:
        if len(selectors) != 1:
            raise StateError("REVIEW_LOCATION_SELECTION_CONFLICT")
        key = next(iter(selectors))
        page = {"comparison_id": "comparisons", "return_id": "returns", "plan_id": "review-returns"}[key]
        if args.page not in ("auto", page):
            raise StateError("REVIEW_LOCATION_PAGE_CONFLICT")
        location = _resolve(library, {"page": page, **selectors})
        if location.get("comparison_id"):
            library.select_comparison(location["comparison_id"])
        return remember_location(library, location)
    if args.page != "auto":
        return _resolve(library, {"page": args.page})
    path = library.state / FILE
    if path.exists() or path.is_symlink():
        saved = parse(read(path, 4096))
        if not isinstance(saved, dict) or saved.get("schema") != SCHEMA:
            raise StateError("REVIEW_LOCATION_INVALID")
        location = {key: value for key, value in saved.items() if key != "schema"}
        # Respect a newer native case selection made in the original browser.
        selected = library.comparisons(limit=1).get("selection") if library.capabilities.get("comparisons") else None
        if not location.get("comparison_id") or selected in (None, location.get("comparison_id")):
            return _resolve(library, location)
    page = "comparisons" if library.capabilities.get("comparisons") else "resources"
    return {"page": page}

#!/usr/bin/env node
// MIT — Python operates the original SF88 library, worker and review writers.
import {randomUUID} from 'node:crypto';
import {createReviewBrowser} from './review-browser.mjs';
import {createJournalBinding,journalActions} from './review-journals.mjs';
import {createResearchBinding,researchActions} from './review-reading.mjs';
import {openLibrary} from '../resource-library/library.mjs';
import {collectionMembers, inspectOriginalCollection, receiveOriginalCollection, openOriginalCollection, collectionDownload} from './review-collections.mjs';
import {readSnapshot, requireValue, digest} from '../resource-library/files.mjs';

const SCHEMA='stellar-forge.sf88.python-review.v1';
const MAX_FRAME=8*1024*1024, CHUNK=1024*1024;
let reportDescriptor,verifyHandover,available=[];
let library=null, browser=null, research=null, journals=null, closing=false, input=Buffer.alloc(0), output=Promise.resolve();
const active=new Map(), transfers=new Map();
const ACTIONS=[...researchActions,...journalActions,'review.receive',
  'library.status','library.scan','library.search','library.resource','library.preview','library.select',
  'annotation.save','annotation.history','collections.list','collections.show','collections.history','collections.save',
  'collections.members','collections.inspectArchive','collections.receiveArchive',
  'comparisons.begin','comparisons.run','comparisons.inspect','comparisons.list','comparisons.select',
  'comparisons.resume','comparisons.cancel','comparisons.wait','comparisons.changes','comparisons.decide',
  'comparisons.history','comparisons.import','returns.stage','returns.list','returns.inspect','returns.targets',
  'returns.choose','returns.apply','returns.decisions','returns.choices','handover.verify',
  'transfer.open','transfer.read','transfer.close','browser.start','browser.status','browser.stop','close'
];
function object(x){return x!==null&&typeof x==='object'&&!Array.isArray(x);}
function errorRecord(e){return {code:/^[A-Z0-9_]{1,120}$/.test(e?.code??'')?e.code:'REVIEW_NATIVE_FAILED',
  status:Number.isInteger(e?.status)?e.status:500};}
function send(frame){
  let raw=Buffer.from(JSON.stringify({schema:SCHEMA,...frame})+'\n');
  if(raw.length>MAX_FRAME)raw=Buffer.from(JSON.stringify({schema:SCHEMA,id:frame.id,ok:false,
    error:{code:'REVIEW_RESPONSE_TOO_LARGE',status:413}})+'\n');
  output=output.then(()=>new Promise((resolve,reject)=>process.stdout.write(raw,error=>error?reject(error):resolve())));
  return output;
}
async function readPacket(parameters){
  requireValue(typeof parameters.path==='string','HANDOVER_PATH_REQUIRED');
  const bytes=await readSnapshot(parameters.path,128*1024*1024);
  if(parameters.sha256!==undefined)requireValue(digest(bytes)===parameters.sha256,'HANDOVER_FILE_DIGEST_MISMATCH',409);
  try{return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}
  catch{requireValue(false,'HANDOVER_JSON_INVALID');}
}
async function releaseTransfer(id){
  const entry=transfers.get(id);if(!entry)return {closed:true};
  transfers.delete(id);await entry.descriptor.dispose();return {closed:true};
}
async function dispatch(action,p,signal){
  if(action==='open'){
    requireValue(!library&&!closing,'REVIEW_ALREADY_OPEN',409);
    const [major,minor]=process.versions.node.split('.').map(Number);
    requireValue(major>22||(major===22&&minor>=16),'REVIEW_NODE_22_16_REQUIRED');
    let collectionReceipt=null;
    if(p.receivedDirectory!==undefined){
      const opened=await openOriginalCollection(p,signal);library=opened.library;collectionReceipt=opened.receipt;
    }else{
      requireValue(p.collectionArchive===undefined&&p.collectionExpectedSha256===undefined&&
        p.collectionMaxBytes===undefined&&!p.collectionResume,'COLLECTION_RECEIVED_DIRECTORY_REQUIRED');
      library=await openLibrary(p);
    }
    browser=createReviewBrowser(library);research=createResearchBinding(library);journals=createJournalBinding(library,{readPacket});
    // The existing source library remains usable while its optional edition
    // product is composed. Never install or synthesize a comparison engine.
    if(library.comparisons){
      ({reportDescriptor}=await import('../resource-library/comparison-transfer.mjs'));
      ({verifyHandover}=await import('../resource-library/comparison-report.mjs'));
    }
    available=ACTIONS.filter(action=>action.startsWith('reviewReturns.')?journals.available:
      action==='review.receive'?Boolean(library.comparisons):action.startsWith('returns.')?Boolean(library.comparisons?.returns):
      action.startsWith('comparisons.')||action==='handover.verify'?Boolean(library.comparisons):true);
    return {schema:SCHEMA,node:process.versions.node,actions:available,
      features:{resources:true,browser:true,collections:true,research:true,comparisons:Boolean(library.comparisons),returns:Boolean(library.comparisons?.returns),reviewReturns:journals.available},
      collectionReceipt,library:library.status()};
  }
  requireValue(library&&!closing,'REVIEW_NOT_OPEN',409);
  requireValue(available.includes(action),'REVIEW_CAPABILITY_UNAVAILABLE',409);
  if(action.startsWith("research."))return research.dispatch(action,p,signal);
  if(action==='review.receive'||action.startsWith('reviewReturns.'))return journals.dispatch(action,p);
  const c=library.comparisons,r=c?.returns,{id,options={},input:body={}}=p;
  switch(action){
    case 'browser.start':return browser.start(p);
    case 'browser.status':return browser.status();
    case 'browser.stop':return browser.stop(p);
    case 'library.status':return library.status();
    case 'library.scan':return library.scan({signal});
    case 'library.search':return library.search(p);
    case 'library.resource':return library.resource(id);
    case 'library.preview':return library.preview(id,{signal});
    case 'library.select':return library.select(id);
    case 'annotation.save':return library.saveAnnotation(id,body);
    case 'annotation.history':return library.revisions(id);
    case 'collections.list':return library.collections.list(p);
    case 'collections.show':return library.collections.show(id,p.revision);
    case 'collections.history':return library.collections.history(id,options);
    case 'collections.save':return library.collections.save(p);
    case 'collections.members':return collectionMembers(library,p);
    case 'collections.inspectArchive':return inspectOriginalCollection(p,signal);
    case 'collections.receiveArchive':return receiveOriginalCollection(p,signal);
    case 'comparisons.begin':return c.begin(p);
    case 'comparisons.run':{const started=c.begin(p);return c.wait(started.id,{signal});}
    case 'comparisons.inspect':return c.inspect(id);
    case 'comparisons.list':return c.list(p);
    case 'comparisons.select':return c.select(id);
    case 'comparisons.resume':{const result=c.resume(id,options);return p.wait?c.wait(id,{signal}):result;}
    case 'comparisons.cancel':return c.cancel(id);
    case 'comparisons.wait':return c.wait(id,{signal});
    case 'comparisons.changes':return c.changes(id,options);
    case 'comparisons.decide':return c.decide(id,body);
    case 'comparisons.history':return c.history(id,options);
    case 'comparisons.import':return c.importHandover(await readPacket(p),{operationId:p.operationId});
    case 'returns.stage':return r.stage(await readPacket(p),{operationId:p.operationId});
    case 'returns.list':return r.list(p);
    case 'returns.inspect':return r.inspect(id);
    case 'returns.targets':return r.targets(id,options);
    case 'returns.choose':return r.choose(id,body);
    case 'returns.apply':return r.apply(id,body);
    case 'returns.decisions':return r.decisionHistory(id,options);
    case 'returns.choices':return r.choiceHistory(id,options);
    case 'handover.verify':{
      const packet=verifyHandover(await readPacket(p));
      return {schema:packet.schema,handoverSha256:packet.handoverSha256,comparisonId:packet.comparison.id,
        resultSha256:packet.comparison.resultSha256,changes:packet.changes.length,decisions:packet.decisions.length};
    }
    case 'transfer.open':{
      requireValue(transfers.size<8,'REVIEW_TRANSFER_CAPACITY',409);
      requireValue(['resource','comparison','return','review-journal','library-review','collection','reading-handover'].includes(p.kind),'REVIEW_TRANSFER_KIND_INVALID');
      let descriptor;
      if(p.kind==='reading-handover')descriptor=await research.download(id,signal);
      else if(p.kind==='resource')descriptor=await library.download(id,{signal});
      else if(p.kind==='collection')descriptor=await collectionDownload(library,p,signal);
      else {
        requireValue(typeof reportDescriptor==='function','REVIEW_COMPARISON_RUNTIME_REQUIRED',409);
        const report=p.kind==='review-journal'?journals.report(id,p.format??'json'):
          p.kind==='return'?r.handover(id,{format:p.format??'json'}):
          p.kind==='library-review'?{filename:'resource-review.json',mime:'application/json',
            chunks:(async function*(){yield JSON.stringify(library.exportReview(),null,2)+'\n';})()}:undefined;
        descriptor=await reportDescriptor(library,id??'resource-review',{format:p.format??'json',signal,report});
      }
      const token=randomUUID(),metadata={token,kind:p.kind,id:id??null,format:p.format??(p.kind==='collection'?'tar':'json'),
        bytes:descriptor.bytes,sha256:descriptor.sha256,name:descriptor.resource.name};
      if(p.kind==='collection')Object.assign(metadata,{revision:descriptor.revision,
        collectionId:descriptor.collectionId,manifestSha256:descriptor.manifestSha256,
        memberCount:descriptor.memberCount,objectCount:descriptor.objectCount});
      transfers.set(token,{descriptor,metadata});return metadata;
    }
    case 'transfer.read':{
      const entry=transfers.get(p.token);requireValue(entry,'REVIEW_TRANSFER_NOT_FOUND',404);
      requireValue(Number.isSafeInteger(p.offset)&&p.offset>=0&&p.offset<=entry.metadata.bytes,'REVIEW_TRANSFER_OFFSET_INVALID');
      const length=p.length??CHUNK;requireValue(Number.isSafeInteger(length)&&length>=1&&length<=CHUNK,'REVIEW_TRANSFER_LENGTH_INVALID');
      const wanted=Math.min(length,entry.metadata.bytes-p.offset),bytes=Buffer.alloc(wanted);let got=0;
      while(got<wanted){signal.throwIfAborted();const part=await entry.descriptor.file.read(bytes,got,wanted-got,p.offset+got);
        requireValue(part.bytesRead>0,'REVIEW_TRANSFER_UNEXPECTED_EOF',409);got+=part.bytesRead;}
      return {token:p.token,offset:p.offset,bytes:got,sha256:digest(bytes),data:bytes.toString('base64'),
        totalBytes:entry.metadata.bytes,nextOffset:p.offset+got===entry.metadata.bytes?null:p.offset+got};
    }
    case 'transfer.close':return releaseTransfer(p.token);
    case 'close':{
      closing=true;for(const controller of active.values())controller.abort();
      for(const token of [...transfers.keys()])await releaseTransfer(token);
      await browser.close();await research.close();await library.close();return {closed:true};
    }
    default:requireValue(false,'REVIEW_ACTION_INVALID');
  }
}
async function shutdown(){
  if(!closing){closing=true;for(const controller of active.values())controller.abort();
    for(const token of [...transfers.keys()])await releaseTransfer(token).catch(()=>{});
    if(browser)await browser.close().catch(()=>{});
    if(research)await research.close().catch(()=>{});
    if(library)await library.close().catch(()=>{});}
  await output.catch(()=>{});
}
async function receive(frame){
  if(object(frame)&&typeof frame.cancel==='string'){active.get(frame.cancel)?.abort();return;}
  let id=object(frame)?frame.id:null;
  try{
    requireValue(object(frame)&&frame.schema===SCHEMA&&typeof id==='string'&&id.length<=100&&
      typeof frame.action==='string'&&object(frame.parameters??{}),'REVIEW_PROTOCOL_INVALID');
    requireValue(!active.has(id)&&active.size<32,'REVIEW_REQUEST_BUSY',409);
    const controller=new AbortController();active.set(id,controller);
    try {const result=await dispatch(frame.action,frame.parameters??{},controller.signal);await send({id,ok:true,result});}
    finally{active.delete(id);}
    if(frame.action==='close'){process.stdin.pause();await output;process.exitCode=0;}
  }catch(error){await send({id,ok:false,error:errorRecord(error)});}
}
process.stdin.on('data',part=>{
  input=Buffer.concat([input,part]);let end;
  while((end=input.indexOf(10))>=0){const line=input.subarray(0,end);input=input.subarray(end+1);
    if(line.length>MAX_FRAME){void send({id:null,ok:false,error:{code:'REVIEW_REQUEST_TOO_LARGE',status:413}});void shutdown();process.stdin.destroy();return;}
    try{void receive(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(line))).catch(()=>shutdown());}
    catch{void send({id:null,ok:false,error:{code:'REVIEW_PROTOCOL_INVALID',status:400}});}
  }
  if(input.length>MAX_FRAME){void shutdown();process.stdin.destroy();}
});
process.stdin.on('end',()=>void shutdown());process.stdin.on('error',()=>void shutdown());
process.stdout.on('error',()=>void shutdown());
for(const signal of ['SIGINT','SIGTERM'])process.once(signal,()=>{process.stdin.destroy();void shutdown();});

