    case 'library.search':return library.search(p);
    case 'library.resource':return library.resource(id);
    case 'library.preview':return library.preview(id,{signal});
    case 'library.select':return library.select(id);
    case 'annotation.save':return library.saveAnnotation(id,body);
    case 'annotation.history':return library.revisions(id);
    case 'collections.list':return library.collections.list(p);
    case 'collections.show':return library.collections.show(id,p.revision);
    case 'collections.history':return library.collections.history(id,options);
    case 'collections.save':return library.collections.save(p);
    case 'comparisons.begin':return c.begin(p);
    case 'comparisons.run':{const started=c.begin(p);return c.wait(started.id,{signal});}
    case 'comparisons.inspect':return c.inspect(id);
    case 'comparisons.list':return c.list(p);
    case 'comparisons.select':return c.select(id);
    case 'comparisons.resume':{const result=c.resume(id,options);return p.wait?c.wait(id,{signal}):result;}
    case 'comparisons.cancel':return c.cancel(id);
    case 'comparisons.wait':return c.wait(id,{signal});
    case 'comparisons.changes':return c.changes(id,options);
    case 'comparisons.decide':return c.decide(id,body);
    case 'comparisons.history':return c.history(id,options);
    case 'comparisons.import':return c.importHandover(await readPacket(p),{operationId:p.operationId});
    case 'returns.stage':return r.stage(await readPacket(p),{operationId:p.operationId});
    case 'returns.list':return r.list(p);
    case 'returns.inspect':return r.inspect(id);
    case 'returns.targets':return r.targets(id,options);
    case 'returns.choose':return r.choose(id,body);
    case 'returns.apply':return r.apply(id,body);
    case 'returns.decisions':return r.decisionHistory(id,options);
    case 'returns.choices':return r.choiceHistory(id,options);
    case 'handover.verify':{
      const packet=verifyHandover(await readPacket(p));
      return {schema:packet.schema,handoverSha256:packet.handoverSha256,comparisonId:packet.comparison.id,
        resultSha256:packet.comparison.resultSha256,changes:packet.changes.length,decisions:packet.decisions.length};
    }
    case 'transfer.open':{
      requireValue(transfers.size<8,'REVIEW_TRANSFER_CAPACITY',409);
      requireValue(['resource','comparison','return','review-journal','library-review'].includes(p.kind),'REVIEW_TRANSFER_KIND_INVALID');
      let descriptor;
      if(p.kind==='resource')descriptor=await library.download(id,{signal});
      else {
        requireValue(typeof reportDescriptor==='function','REVIEW_COMPARISON_RUNTIME_REQUIRED',409);
        const report=p.kind==='review-journal'?journals.report(id,p.format??'json'):
          p.kind==='return'?r.handover(id,{format:p.format??'json'}):
          p.kind==='library-review'?{filename:'resource-review.json',mime:'application/json',
            chunks:(async function*(){yield JSON.stringify(library.exportReview(),null,2)+'\n';})()}:undefined;
        descriptor=await reportDescriptor(library,id??'resource-review',{format:p.format??'json',signal,report});
      }
      const token=randomUUID(),metadata={token,kind:p.kind,id:id??null,format:p.format??'json',
        bytes:descriptor.bytes,sha256:descriptor.sha256,name:descriptor.resource.name};
      transfers.set(token,{descriptor,metadata});return metadata;
    }
    case 'transfer.read':{
      const entry=transfers.get(p.token);requireValue(entry,'REVIEW_TRANSFER_NOT_FOUND',404);
      requireValue(Number.isSafeInteger(p.offset)&&p.offset>=0&&p.offset<=entry.metadata.bytes,'REVIEW_TRANSFER_OFFSET_INVALID');
      const length=p.length??CHUNK;requireValue(Number.isSafeInteger(length)&&length>=1&&length<=CHUNK,'REVIEW_TRANSFER_LENGTH_INVALID');
      const wanted=Math.min(length,entry.metadata.bytes-p.offset),bytes=Buffer.alloc(wanted);let got=0;
      while(got<wanted){signal.throwIfAborted();const part=await entry.descriptor.file.read(bytes,got,wanted-got,p.offset+got);
        requireValue(part.bytesRead>0,'REVIEW_TRANSFER_UNEXPECTED_EOF',409);got+=part.bytesRead;}
      return {token:p.token,offset:p.offset,bytes:got,sha256:digest(bytes),data:bytes.toString('base64'),
        totalBytes:entry.metadata.bytes,nextOffset:p.offset+got===entry.metadata.bytes?null:p.offset+got};
    }
    case 'transfer.close':return releaseTransfer(p.token);
    case 'close':{
      closing=true;for(const controller of active.values())controller.abort();
      for(const token of [...transfers.keys()])await releaseTransfer(token);
      await browser.close();await library.close();return {closed:true};
    }
    default:requireValue(false,'REVIEW_ACTION_INVALID');
  }
}
async function shutdown(){
  if(!closing){closing=true;for(const controller of active.values())controller.abort();
    for(const token of [...transfers.keys()])await releaseTransfer(token).catch(()=>{});
    if(browser)await browser.close().catch(()=>{});
    if(library)await library.close().catch(()=>{});}
  await output.catch(()=>{});
}
async function receive(frame){
  if(object(frame)&&typeof frame.cancel==='string'){active.get(frame.cancel)?.abort();return;}
  let id=object(frame)?frame.id:null;
  try{
    requireValue(object(frame)&&frame.schema===SCHEMA&&typeof id==='string'&&id.length<=100&&
      typeof frame.action==='string'&&object(frame.parameters??{}),'REVIEW_PROTOCOL_INVALID');
    requireValue(!active.has(id)&&active.size<32,'REVIEW_REQUEST_BUSY',409);
    const controller=new AbortController();active.set(id,controller);
    try {const result=await dispatch(frame.action,frame.parameters??{},controller.signal);await send({id,ok:true,result});}
    finally{active.delete(id);}
    if(frame.action==='close'){process.stdin.pause();await output;process.exitCode=0;}
  }catch(error){await send({id,ok:false,error:errorRecord(error)});}
}
process.stdin.on('data',part=>{
  input=Buffer.concat([input,part]);let end;
  while((end=input.indexOf(10))>=0){const line=input.subarray(0,end);input=input.subarray(end+1);
    if(line.length>MAX_FRAME){void send({id:null,ok:false,error:{code:'REVIEW_REQUEST_TOO_LARGE',status:413}});void shutdown();process.stdin.destroy();return;}
    try{void receive(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(line))).catch(()=>shutdown());}
    catch{void send({id:null,ok:false,error:{code:'REVIEW_PROTOCOL_INVALID',status:400}});}
  }
  if(input.length>MAX_FRAME){void shutdown();process.stdin.destroy();}
});
process.stdin.on('end',()=>void shutdown());process.stdin.on('error',()=>void shutdown());
process.stdout.on('error',()=>void shutdown());
for(const signal of ['SIGINT','SIGTERM'])process.once(signal,()=>{process.stdin.destroy();void shutdown();});

"""Python customer resource review through the maintained native SF88 engine.

No SQLite schema, comparison algorithm, decision journal, or reconciliation rule
is implemented here. Every application operation delegates to its original owner.
"""
from __future__ import annotations

from dataclasses import dataclass, field
import os
from pathlib import Path
from typing import Any, Iterator, Literal

from ._review_transport import ReviewError, ReviewTransport, absolute
from ._review_transfer import ReviewFile, ReviewTransferError, TransferProgress, copy_native_file
from .review_journals import JournalDelivery, JournalReturn, ReviewReception
from .errors import StateError
from .storage import private_directory, read, write

ReviewStatus = Literal["ACCEPT", "REJECT", "FOLLOW_UP"]
ReviewChoice = Literal["KEEP_LOCAL", "TAKE_INCOMING", "CUSTOM"]
ReportFormat = Literal["json", "csv", "html"]
ComparisonFormat = Literal["auto", "json", "csv", "text", "bytes"]


def _present(**values):
    return {key: value for key, value in values.items() if value is not None}


def _iterate(fetch, *, page_size=100, **options) -> Iterator[dict[str, Any]]:
    """Traverse the actual native cursor. Concurrent edits require a fresh scan."""
    if type(page_size) is not int or not 1 <= page_size <= 200:
        raise StateError("REVIEW_PAGE_SIZE_INVALID")
    offset, expected_total, generation = 0, None, None
    while True:
        page = fetch(offset=offset, limit=page_size, **options)
        total, items = page.get("total"), page.get("items")
        if type(total) is not int or total < 0 or not isinstance(items, list) or page.get("offset", offset) != offset:
            raise StateError("REVIEW_PAGE_INVALID")
        current = (page.get("scan") or {}).get("generation") or page.get("planSha256")
        if expected_total is not None and (total != expected_total or current != generation):
            raise StateError("REVIEW_PAGE_CHANGED")
        expected_total, generation = total, current
        yield from items
        offset += len(items)
        if offset >= total:
            return
        if not items:
            raise StateError("REVIEW_PAGE_INCOMPLETE")


class ResourceLibrary(JournalDelivery):
    """Owns a native process, not a second resource store. Always close or use with."""
    def __init__(self, *, checkout, state, node="node", kind=None, source=None,
                 roots=None, max_file_bytes=None, index_bytes=None,
                 timeout=360.0, environment=None):
        self.state = Path(absolute(state))
        self.checkout = Path(absolute(checkout))
        configuration = _present(state=str(self.state), kind=kind,
            source=None if source is None else absolute(source),
            roots=None if roots is None else [absolute(path) for path in roots],
            maxFileBytes=max_file_bytes, indexBytes=index_bytes)
        self._transport = ReviewTransport(checkout=str(self.checkout), node=node,
            configuration=configuration, timeout=timeout, environment=environment)
        self.runtime = self._transport.opened

    @classmethod
    def from_buyer(cls, buyer, *, state, **options):
        """Reuse the original Buyer's chosen checkout/runtime; no purchase is started."""
        runtime = getattr(buyer, "runtime", None)
        if runtime is None or not hasattr(runtime, "checkout"):
            raise StateError("ORIGINAL_BUYER_RUNTIME_REQUIRED")
        return cls(checkout=runtime.checkout, state=state, node=runtime.node,
                   environment=runtime.environment, timeout=runtime.timeout, **options)

    @classmethod
    def receiver(cls, *, checkout, state, **options):
        """Create/open an original empty snapshot library for portable review intake."""
        state = Path(absolute(state))
        if state.resolve() != state:
            raise StateError("REVIEW_CANONICAL_STATE_REQUIRED")
        state = private_directory(state)
        if (state / "library.sqlite").exists():
            return cls(checkout=checkout, state=state, **options)
        source, files = state / "receiver-source.json", state / "receiver-files"
        private_directory(files)
        if source.exists() or source.is_symlink():
            if read(source, 16) != b"[]\n":
                raise StateError("REVIEW_RECEIVER_SOURCE_CONFLICT")
        else:
            write(source, b"[]\n", exclusive=True)
        return cls(checkout=checkout, state=state, kind="snapshot", source=source,
                   roots=[files], **options)

    @property
    def capabilities(self) -> dict[str, bool]:
        return dict(self.runtime["features"])

    @property
    def pid(self) -> int:
        return self._transport.pid

    def _call(self, action, parameters=None, **options):
        return self._transport.call(action, parameters, **options)

    def invoke(self, action: str, parameters=None, *, timeout=None, cancel_event=None):
        """The declared native actions only; useful for a newer compatible field."""
        if action not in self.runtime["actions"] or action == "close":
            raise StateError("REVIEW_ACTION_INVALID")
        return self._call(action, parameters, timeout=timeout, cancel_event=cancel_event)

    def browser(self, *, port=0, page="resources", operation_id=None):
        """Start the original browser on this same native library/process."""
        from .review_browser import ReviewBrowser
        return ReviewBrowser.start(self, port=port, page=page, operation_id=operation_id)

    def browser_status(self):
        """Return token-free lifecycle state from the original listener owner."""
        return self.invoke("browser.status")

    def status(self):
        return self._call("library.status")

    def scan(self, *, cancel_event=None, timeout=None):
        return self._call("library.scan", cancel_event=cancel_event, timeout=timeout)

    def search(self, *, q="", offset=0, limit=50, status="", starred=False):
        return self._call("library.search", dict(q=q, offset=offset, limit=limit, status=status, starred=starred))

    def iter_resources(self, *, page_size=100, **filters):
        return _iterate(self.search, page_size=page_size, **filters)

    def resource(self, resource_id: str):
        return self._call("library.resource", {"id": resource_id})

    def preview(self, resource_id: str, *, cancel_event=None):
        return self._call("library.preview", {"id": resource_id}, cancel_event=cancel_event)

    def select_resource(self, resource_id: str | None):
        return self._call("library.select", {"id": resource_id})

    def annotate(self, resource_id: str, *, expected_revision: int, operation_id: str,
                 note=None, tags=None, starred=None):
        return self._call("annotation.save", {"id": resource_id, "input": _present(
            expectedRevision=expected_revision, operationId=operation_id,
            note=note, tags=tags, starred=starred)})

    def annotation_history(self, resource_id: str):
        return self._call("annotation.history", {"id": resource_id})

    def collections(self, *, offset=0, limit=50):
        return self._call("collections.list", dict(offset=offset, limit=limit))

    def collection(self, collection_id: str, *, revision=None):
        return self._call("collections.show", _present(id=collection_id, revision=revision))

    def collection_history(self, collection_id: str, *, offset=0, limit=50):
        return self._call("collections.history", {"id": collection_id, "options": dict(offset=offset, limit=limit)})

    def save_collection(self, *, collection_id: str, name: str, members: list[dict],
                        expected_revision: int, operation_id: str, note=None):
        return self._call("collections.save", _present(id=collection_id, name=name,
            members=members, expectedRevision=expected_revision, operationId=operation_id, note=note))

    def comparisons(self, *, offset=0, limit=50):
        return self._call("comparisons.list", dict(offset=offset, limit=limit))

    def iter_comparisons(self, *, page_size=100):
        return _iterate(self.comparisons, page_size=page_size)

    def comparison(self, comparison_id: str) -> Comparison:
        record = self._call("comparisons.inspect", {"id": comparison_id})
        return Comparison(record["id"], self, record)

    def select_comparison(self, comparison_id: str | None):
        return self._call("comparisons.select", {"id": comparison_id})

    def compare(self, before_id: str, after_id: str, *, operation_id: str,
                format: ComparisonFormat = "auto", key_columns=None, max_input_bytes=None,
                max_nodes=None, max_changes=None, wait=True, cancel_event=None, timeout=None) -> Comparison:
        parameters = _present(beforeId=before_id, afterId=after_id, operationId=operation_id,
            format=format, keyColumns=key_columns, maxInputBytes=max_input_bytes,
            maxNodes=max_nodes, maxChanges=max_changes)
        record = self._call("comparisons.run" if wait else "comparisons.begin", parameters,
                            cancel_event=cancel_event, timeout=timeout)
        return Comparison(record["id"], self, record)

    def import_review(self, path, *, operation_id: str, expected_sha256=None) -> Comparison:
        record = self._call("comparisons.import", _present(path=absolute(path),
            operationId=operation_id, sha256=expected_sha256))
        return Comparison(record["id"], self, record)

    def verify_review(self, path, *, expected_sha256=None):
        return self._call("handover.verify", _present(path=absolute(path), sha256=expected_sha256))

    def stage_return(self, path, *, operation_id: str, expected_sha256=None) -> ReviewReturn:
        record = self._call("returns.stage", _present(path=absolute(path),
            operationId=operation_id, sha256=expected_sha256))
        return ReviewReturn(record["id"], self, record)

    def review_return(self, return_id: str) -> ReviewReturn:
        record = self._call("returns.inspect", {"id": return_id})
        return ReviewReturn(record["id"], self, record)

    def returns(self, *, comparison_id=None, offset=0, limit=50):
        return self._call("returns.list", _present(comparisonId=comparison_id, offset=offset, limit=limit))

    def iter_returns(self, *, comparison_id=None, page_size=100):
        return _iterate(self.returns, comparison_id=comparison_id, page_size=page_size)

    def download_resource(self, resource_id: str, destination, **options) -> ReviewFile:
        return copy_native_file(self, {"kind": "resource", "id": resource_id}, destination, **options)

    def export_resource_review(self, destination, **options) -> ReviewFile:
        return copy_native_file(self, {"kind": "library-review"}, destination, **options)

    def close(self):
        self._transport.close()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()


@dataclass
class Comparison:
    id: str
    _library: ResourceLibrary = field(repr=False)
    observed: dict[str, Any] = field(repr=False)

    def inspect(self):
        self.observed = self._library._call("comparisons.inspect", {"id": self.id})
        return self.observed

    def wait(self, *, timeout=None, cancel_event=None):
        self.observed = self._library._call("comparisons.wait", {"id": self.id},
            timeout=timeout, cancel_event=cancel_event)
        return self.observed

    def cancel(self):
        self.observed = self._library._call("comparisons.cancel", {"id": self.id})
        return self.observed

    def resume(self, *, operation_id: str, wait=True, timeout=None, cancel_event=None):
        self.observed = self._library._call("comparisons.resume", {"id": self.id,
            "options": {"operationId": operation_id}, "wait": wait}, timeout=timeout, cancel_event=cancel_event)
        return self.observed

    def changes(self, *, offset=0, limit=50, type="", q="", review=""):
        return self._library._call("comparisons.changes", {"id": self.id,
            "options": dict(offset=offset, limit=limit, type=type, q=q, review=review)})

    def iter_changes(self, *, page_size=100, **filters):
        return _iterate(self.changes, page_size=page_size, **filters)

    def decide(self, *, target="*", expected_revision: int, operation_id: str,
               status: ReviewStatus, actor: str, note=""):
        return self._library._call("comparisons.decide", {"id": self.id, "input": dict(
            target=target, expectedRevision=expected_revision, operationId=operation_id,
            status=status, actor=actor, note=note)})

    def history(self, *, target=None):
        return self._library._call("comparisons.history", {"id": self.id, "options": _present(target=target)})

    def export(self, destination, *, format: ReportFormat = "json", **options) -> ReviewFile:
        return copy_native_file(self._library, {"kind": "comparison", "id": self.id,
            "format": format}, destination, **options)

    def export_journal(self, destination, *, format: ReportFormat = "json", **options) -> ReviewFile:
        return self._library.export_journal(self.id, destination, format=format, **options)

    def journal_returns(self, *, offset=0, limit=50):
        return self._library.journal_returns(comparison_id=self.id, offset=offset, limit=limit)

    def returns(self, *, offset=0, limit=50):
        return self._library.returns(comparison_id=self.id, offset=offset, limit=limit)


@dataclass
class ReviewReturn:
    id: str
    _library: ResourceLibrary = field(repr=False)
    observed: dict[str, Any] = field(repr=False)

    def inspect(self):
        self.observed = self._library._call("returns.inspect", {"id": self.id})
        return self.observed

    def targets(self, *, offset=0, limit=50, state=""):
        return self._library._call("returns.targets", {"id": self.id,
            "options": dict(offset=offset, limit=limit, state=state)})

    def iter_targets(self, *, page_size=100, state=""):
        return _iterate(self.targets, page_size=page_size, state=state)

    def choose(self, *, target: str, plan_sha256: str, expected_revision: int,
               operation_id: str, choice: ReviewChoice, actor: str, note: str,
               status: ReviewStatus | None = None):
        return self._library._call("returns.choose", {"id": self.id, "input": _present(
            target=target, planSha256=plan_sha256, expectedRevision=expected_revision,
            operationId=operation_id, choice=choice, actor=actor, note=note, status=status)})

    def apply(self, *, plan_sha256: str, operation_id: str):
        return self._library._call("returns.apply", {"id": self.id,
            "input": dict(planSha256=plan_sha256, operationId=operation_id)})

    def decision_history(self, *, target: str, side="incoming", offset=0, limit=50):
        return self._library._call("returns.decisions", {"id": self.id,
            "options": dict(target=target, side=side, offset=offset, limit=limit)})

    def choice_history(self, *, target: str, offset=0, limit=50):
        return self._library._call("returns.choices", {"id": self.id,
            "options": dict(target=target, offset=offset, limit=limit)})

    def export_original(self, destination, *, format: ReportFormat = "json", **options) -> ReviewFile:
        return copy_native_file(self._library, {"kind": "return", "id": self.id,
            "format": format}, destination, **options)


__all__ = ["ResourceLibrary", "Comparison", "ReviewReturn", "JournalReturn", "ReviewReception", "ReviewFile", "ReviewError",
           "ReviewTransferError", "TransferProgress", "ReviewStatus", "ReviewChoice", "ReportFormat"]

"""Command line for the complete original Python resource-review workflow."""
from __future__ import annotations

import argparse
from dataclasses import asdict, is_dataclass
import json
from pathlib import Path
import sys

from .errors import BuyerError
from .review_library import ResourceLibrary, ReviewError, ReviewTransferError
from .storage import parse, read
from .review_serve import browser_arguments, serve_foreground
from .review_journal_cli import add_journal_commands, execute_journal
from .review_location import remember_receipt


def _print(value):
    if is_dataclass(value):
        value = asdict(value)
    print(json.dumps(value, ensure_ascii=False, allow_nan=False, indent=2, default=str))


def _json_file(path):
    value = parse(read(Path(path), 8 * 1024 * 1024))
    if not isinstance(value, dict):
        raise BuyerError("REVIEW_JSON_OBJECT_REQUIRED")
    return value


def parser():
    root = argparse.ArgumentParser(description="Original SF88 resource library, edition review and reviewer returns")
    root.add_argument("--checkout", required=True, help="Absolute original source root")
    root.add_argument("--state", required=True, help="Absolute native library state directory")
    root.add_argument("--node", default="node")
    root.add_argument("--timeout", type=float, default=360)
    commands = root.add_subparsers(dest="command", required=True)
    init = commands.add_parser("init", help="Initialize an original source or a portable-review receiver")
    init.add_argument("--receiver", action="store_true")
    init.add_argument("--kind", choices=["inbox", "snapshot", "collection", "paid-jobs"], default="snapshot")
    init.add_argument("--source")
    init.add_argument("--files-root", action="append")
    init.add_argument("--max-file-bytes", type=int)
    init.add_argument("--index-bytes", type=int)
    serve = commands.add_parser("serve", help="Open the original browser on this Python-owned native library")
    serve.add_argument("--receiver", action="store_true", help="Create a portable-review receiver if needed")
    browser_arguments(serve)
    receive = commands.add_parser("receive", help="Receive a complete handover into an independent editable workspace")
    receive.add_argument("--input", required=True)
    receive.add_argument("--operation-id", required=True, help="Reuse the same identity to recover a lost reply")
    receive.add_argument("--sha256")
    receive.add_argument("--stage-return", action="store_true", help="Stage against a comparison already present here")
    receive.add_argument("--return-format", choices=["auto", "incoming", "returned"], default="auto",
        help="Auto keeps incoming handovers and recognizes complete journal envelopes")
    receive.add_argument("--label", help="Label for an explicitly staged full-journal return")
    receive.add_argument("--serve", action="store_true", help="Continue directly into the original browser")
    browser_arguments(receive, selection=False)
    commands.add_parser("status")
    commands.add_parser("capabilities", help="Actual selected native engine features and action names")
    commands.add_parser("scan")
    resources = commands.add_parser("resources")
    _page(resources)
    resources.add_argument("--query", default="")
    resources.add_argument("--status", default="", choices=["", "VERIFIED", "UNAVAILABLE", "INCOMPLETE"])
    resources.add_argument("--starred", action="store_true")
    resources.add_argument("--all", action="store_true", help="Stream all matching resources as NDJSON")
    resource = commands.add_parser("resource")
    resource.add_argument("id")
    resource.add_argument("--preview", action="store_true")
    resource.add_argument("--history", action="store_true")
    download = commands.add_parser("download")
    download.add_argument("id")
    _download(download)
    annotations = commands.add_parser("annotate")
    annotations.add_argument("id")
    annotations.add_argument("--input", required=True, help="Original expectedRevision/operationId/note/tags/starred JSON")
    export = commands.add_parser("export-resources")
    _download(export)
    collections = commands.add_parser("collection").add_subparsers(dest="subcommand", required=True)
    _page(collections.add_parser("list"))
    for command in ("show", "history"):
        c = collections.add_parser(command)
        c.add_argument("id")
        if command == "show":
            c.add_argument("--revision", type=int)
        else:
            _page(c)
    save = collections.add_parser("save")
    save.add_argument("--input", required=True)
    compare = commands.add_parser("compare").add_subparsers(dest="subcommand", required=True)
    run = compare.add_parser("run", help="Begin and finish the original worker in this process")
    run.add_argument("--before", required=True)
    run.add_argument("--after", required=True)
    run.add_argument("--operation-id", required=True)
    run.add_argument("--format", choices=["auto", "json", "csv", "text", "bytes"], default="auto")
    run.add_argument("--key-column", action="append")
    run.add_argument("--max-input-bytes", type=int)
    run.add_argument("--max-nodes", type=int)
    run.add_argument("--max-changes", type=int)
    _page(compare.add_parser("list"))
    for command in ("show", "wait", "cancel", "resume", "changes", "history", "decide", "export"):
        c = compare.add_parser(command)
        c.add_argument("id")
        if command == "resume":
            c.add_argument("--operation-id", required=True)
        elif command == "changes":
            _page(c)
            c.add_argument("--type", default="")
            c.add_argument("--query", default="")
            c.add_argument("--review", default="")
            c.add_argument("--all", action="store_true")
        elif command == "history":
            c.add_argument("--target")
        elif command == "decide":
            _decision(c)
        elif command == "export":
            _download(c, formats=True)
    receive = compare.add_parser("receive")
    receive.add_argument("--input", required=True)
    receive.add_argument("--sha256")
    receive.add_argument("--operation-id", required=True)
    verify = compare.add_parser("verify")
    verify.add_argument("--input", required=True)
    verify.add_argument("--sha256")
    returns = commands.add_parser("return").add_subparsers(dest="subcommand", required=True)
    stage = returns.add_parser("stage")
    stage.add_argument("--input", required=True)
    stage.add_argument("--sha256")
    stage.add_argument("--operation-id", required=True)
    listing = returns.add_parser("list")
    listing.add_argument("--comparison-id")
    _page(listing)
    for command in ("show", "targets", "history", "choose", "apply", "export"):
        c = returns.add_parser(command)
        c.add_argument("id")
        if command == "targets":
            _page(c)
            c.add_argument("--state-filter", default="")
            c.add_argument("--all", action="store_true")
        elif command == "history":
            _page(c)
            c.add_argument("--target", required=True)
            c.add_argument("--side", choices=["local", "incoming", "choices"], default="incoming")
        elif command == "choose":
            c.add_argument("--target", required=True)
            c.add_argument("--plan", required=True)
            c.add_argument("--expected-revision", required=True, type=int)
            c.add_argument("--operation-id", required=True)
            c.add_argument("--choice", required=True, choices=["KEEP_LOCAL", "TAKE_INCOMING", "CUSTOM"])
            c.add_argument("--actor", required=True)
            c.add_argument("--note", required=True)
            c.add_argument("--status", choices=["ACCEPT", "REJECT", "FOLLOW_UP"])
        elif command == "apply":
            c.add_argument("--plan", required=True)
            c.add_argument("--operation-id", required=True)
        elif command == "export":
            _download(c, formats=True)
    add_journal_commands(commands, page_arguments=_page, download_arguments=_download)
    return root


def _page(parser):
    parser.add_argument("--offset", type=int, default=0)
    parser.add_argument("--limit", type=int, default=100)


def _download(parser, formats=False):
    parser.add_argument("--out", required=True)
    parser.add_argument("--transfer-directory")
    parser.add_argument("--chunk-bytes", type=int, default=1024 * 1024)
    if formats:
        parser.add_argument("--format", choices=["json", "csv", "html"], default="json")


def _decision(parser):
    parser.add_argument("--target", default="*")
    parser.add_argument("--expected-revision", required=True, type=int)
    parser.add_argument("--operation-id", required=True)
    parser.add_argument("--status", required=True, choices=["ACCEPT", "REJECT", "FOLLOW_UP"])
    parser.add_argument("--actor", required=True)
    parser.add_argument("--note", default="")


def _all(items):
    for item in items:
        print(json.dumps(item, ensure_ascii=False, allow_nan=False, separators=(",", ":")))
    return None


def execute(library, a):
    command, sub = a.command, getattr(a, "subcommand", None)
    if command == "serve":
        return serve_foreground(library, a)
    if command == "receive":
        reception = library.receive_review(a.input, operation_id=a.operation_id,
            expected_sha256=a.sha256, stage_return=a.stage_return,
            return_format=a.return_format, label=a.label)
        received = reception.observed
        remember_receipt(library, received, return_format=reception.format)
        return serve_foreground(library, a, received=received, return_format=reception.format) if a.serve else received
    if command == "review-returns":
        return execute_journal(library, a, json_file=_json_file, all_items=_all)
    if command in ("init", "status"):
        return library.status()
    if command == "capabilities":
        return {"node": library.runtime["node"], "features": library.capabilities, "actions": library.runtime["actions"]}
    if command == "scan":
        return library.scan()
    if command == "resources":
        filters = dict(q=a.query, status=a.status, starred=a.starred)
        return _all(library.iter_resources(page_size=a.limit, **filters)) if a.all else library.search(offset=a.offset, limit=a.limit, **filters)
    if command == "resource":
        return library.annotation_history(a.id) if a.history else library.preview(a.id) if a.preview else library.resource(a.id)
    if command == "annotate":
        return library.invoke("annotation.save", {"id": a.id, "input": _json_file(a.input)})
    if command in ("download", "export-resources"):
        options = dict(transfer_directory=a.transfer_directory, chunk_bytes=a.chunk_bytes)
        return library.download_resource(a.id, a.out, **options) if command == "download" else library.export_resource_review(a.out, **options)
    if command == "collection":
        if sub == "list":return library.collections(offset=a.offset, limit=a.limit)
        if sub == "show":return library.collection(a.id, revision=a.revision)
        if sub == "history":return library.collection_history(a.id, offset=a.offset, limit=a.limit)
        return library.invoke("collections.save", _json_file(a.input))
    if command == "compare":
        if sub == "run":
            return library.compare(a.before, a.after, operation_id=a.operation_id, format=a.format,
                key_columns=a.key_column, max_input_bytes=a.max_input_bytes, max_nodes=a.max_nodes,
                max_changes=a.max_changes).observed
        if sub == "list":return library.comparisons(offset=a.offset, limit=a.limit)
        if sub == "receive":return library.import_review(a.input, operation_id=a.operation_id, expected_sha256=a.sha256).observed
        if sub == "verify":return library.verify_review(a.input, expected_sha256=a.sha256)
        c = library.comparison(a.id)
        if sub == "show":return c.observed
        if sub == "wait":return c.wait()
        if sub == "cancel":return c.cancel()
        if sub == "resume":return c.resume(operation_id=a.operation_id)
        if sub == "history":return c.history(target=a.target)
        if sub == "changes":
            filters = dict(type=a.type, q=a.query, review=a.review)
            return _all(c.iter_changes(page_size=a.limit, **filters)) if a.all else c.changes(offset=a.offset, limit=a.limit, **filters)
        if sub == "decide":return c.decide(target=a.target, expected_revision=a.expected_revision,
            operation_id=a.operation_id, status=a.status, actor=a.actor, note=a.note)
        if sub == "export":return c.export(a.out, format=a.format,
            transfer_directory=a.transfer_directory, chunk_bytes=a.chunk_bytes)
    if command == "return":
        if sub == "stage":
            received = library.stage_return(a.input, operation_id=a.operation_id, expected_sha256=a.sha256).observed
            remember_receipt(library, received, return_format="incoming")
            return received
        if sub == "list":return library.returns(comparison_id=a.comparison_id, offset=a.offset, limit=a.limit)
        r = library.review_return(a.id)
        if sub == "show":return r.observed
        if sub == "targets":return _all(r.iter_targets(page_size=a.limit, state=a.state_filter)) if a.all else r.targets(offset=a.offset, limit=a.limit, state=a.state_filter)
        if sub == "history":
            options = dict(target=a.target, offset=a.offset, limit=a.limit)
            return r.choice_history(**options) if a.side == "choices" else r.decision_history(side=a.side, **options)
        if sub == "choose":return r.choose(target=a.target, plan_sha256=a.plan,
            expected_revision=a.expected_revision, operation_id=a.operation_id, choice=a.choice,
            actor=a.actor, note=a.note, status=a.status)
        if sub == "apply":return r.apply(plan_sha256=a.plan, operation_id=a.operation_id)
        if sub == "export":return r.export_original(a.out, format=a.format,
            transfer_directory=a.transfer_directory, chunk_bytes=a.chunk_bytes)
    raise BuyerError("REVIEW_COMMAND_INVALID")


def main(argv=None):
    p = parser()
    args = p.parse_args(argv)
    options = dict(checkout=args.checkout, state=args.state, node=args.node, timeout=args.timeout)
    try:
        if (args.command == "receive" or (args.command == "serve" and args.receiver)
                or (args.command == "review-returns" and args.subcommand in ("receive", "verify"))):
            library = ResourceLibrary.receiver(**options)
        elif args.command == "init":
            if args.receiver:
                if args.source or args.files_root:
                    p.error("--receiver uses its own original empty source; omit --source and --files-root")
                library = ResourceLibrary.receiver(**options)
            else:
                if not args.source or not args.files_root:
                    p.error("source initialization needs --source and --files-root")
                library = ResourceLibrary(**options, kind=args.kind, source=args.source,
                    roots=args.files_root, max_file_bytes=args.max_file_bytes, index_bytes=args.index_bytes)
        else:
            library = ResourceLibrary(**options)
        with library:
            result = execute(library, args)
            if result is not None:
                _print(result)
        return 0
    except (BuyerError, OSError) as error:
        result = {"error": getattr(error, "code", "REVIEW_IO_ERROR")}
        if isinstance(error, ReviewError):
            result.update(action=error.action, operationId=error.operation_id, dispatched=error.dispatched)
            if error.result is not None:
                result["nativeResult"] = error.result
        if isinstance(error, ReviewTransferError):
            result["transfer"] = asdict(error.progress)
        print(json.dumps(result, ensure_ascii=False, default=str), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Foreground command lifetime for the original Python-owned review browser."""
from __future__ import annotations

import json
import os
from pathlib import Path
import signal
import threading
from typing import Any

from ._review_transport import absolute, ReviewError
from .storage import private_directory, read, write, sync_directory
from .errors import StateError
from .review_location import resolve_location


def browser_arguments(parser, *, selection=True):
    parser.add_argument("--port", type=int, default=0, help="Loopback port; zero selects a free port")
    parser.add_argument("--page", choices=["auto", "resources", "comparisons", "returns", "review-returns", "collections"], default="auto")
    parser.add_argument("--open-browser", action="store_true", help="Explicitly open the local desktop browser")
    parser.add_argument("--show-url", action="store_true", help="Print the private session URL to this terminal")
    parser.add_argument("--ready-file", help="New JSON file in an existing private directory; contains private session URL")
    parser.add_argument("--browser-operation-id", help="Optional identity for retrying this process's listener start")
    if selection:
        target = parser.add_mutually_exclusive_group()
        target.add_argument("--comparison-id", help="Open this original comparison")
        target.add_argument("--return-id", help="Open this saved incoming return")
        target.add_argument("--plan-id", help="Open this saved full-journal return plan")


def serve_foreground(library, args, *, received: dict[str, Any] | None = None, return_format=None):
    ready_path = None
    if args.ready_file:
        ready_path = Path(absolute(args.ready_file))
        if private_directory(ready_path.parent, create=False) != ready_path.parent:
            raise StateError("REVIEW_CANONICAL_CONNECTION_PATH_REQUIRED")
        if ready_path.exists() or ready_path.is_symlink():
            raise StateError("REVIEW_CONNECTION_FILE_EXISTS")
    location = resolve_location(library, args, received=received, return_format=return_format)
    page = location["page"]
    selectors = {key: value for key, value in location.items() if key != "page"}
    stop = threading.Event()
    prior = {}
    raw = None
    try:
        for sig in (signal.SIGINT, signal.SIGTERM):
            prior[sig] = signal.getsignal(sig)
            signal.signal(sig, lambda *_: stop.set())
        with library.browser(port=args.port, page=page, operation_id=args.browser_operation_id) as browser:
            url = browser.page_url(page, **selectors)
            private = {"schema": "stellar-forge.python-review-connection.v1", **browser.metadata(),
                       "stateDirectory": str(library.state), "location": location, "url": url}
            if ready_path:
                raw = (json.dumps(private, ensure_ascii=False, indent=2) + "\n").encode()
                write(ready_path, raw, exclusive=True)
            message = {"event": "listening", **browser.metadata(), "stateDirectory": str(library.state), "location": location}
            if ready_path:
                message["readyFile"] = str(ready_path)
            if args.show_url:
                message["url"] = url
            if args.open_browser:
                message["browserOpened"] = browser.open_tab(page, **selectors)
            if received:
                message["received"] = {key: received[key] for key in ("kind", "id", "state", "status", "comparisonId", "planId") if key in received}
                if return_format:
                    message["received"]["format"] = return_format
                if received.get("kind") == "collection" and received.get("receipt"):
                    message["received"].update({key: received["receipt"][key]
                        for key in ("collectionId", "revision", "manifestSha256", "sha256", "memberCount")})
            print(json.dumps(message, ensure_ascii=False), flush=True)
            while not stop.wait(0.25):
                if library._transport.process.poll() is not None:
                    raise ReviewError("REVIEW_PROCESS_ENDED", action="browser.wait")
            return {"event": "closed", "stateDirectory": str(library.state)}
    finally:
        for sig, handler in prior.items():
            signal.signal(sig, handler)
        # Do not delete a connection file someone else has replaced while running.
        if ready_path and raw is not None:
            try:
                if read(ready_path, 65536) == raw:
                    ready_path.unlink()
                    sync_directory(ready_path.parent)
            except (OSError, StateError):
                pass
